WITH b AS (SELECT c.ano,c.id_contratacao_pncp,c.id_municipio,m.nome municipio,c.data_publicacao,c.nome_orgao,c.objeto_compra,c.valor_total_estimado,c.valor_total_homologado,c.link_sistema_origem,LOWER(REGEXP_REPLACE(COALESCE(c.objeto_compra,''),r'mata de são joão|mata de sao joao','')) texto FROM `basedosdados.br_mgi_pncp.contratacao` c JOIN `basedosdados.br_bd_diretorios_brasil.municipio` m ON c.id_municipio=m.id_municipio WHERE c.ano BETWEEN 2021 AND 2026 AND m.sigla_uf='BA'), f AS (SELECT *,CASE WHEN REGEXP_CONTAINS(texto,r'\bcarnaval\b|\bsão joão\b|\bsao joao\b|\bfesta junina\b|\bfestas juninas\b|\bfestividade|\bfestejo|\bfesta popular|\bfestas populares|\bfestas tradicionais|\bcomemoração de .*?(festa|evento|aniversário|aniversario)|\bcomemoracao de .*?(festa|evento|aniversario)|\barr[aá]i[aá]\b|\br[eé]veillon\b') THEN 'Festas populares e comemorações' WHEN REGEXP_CONTAINS(texto,r'\bartista\b|\bartistas\b|\bcantor\b|\bcantora\b|\bbanda\b|\bm[uú]sico\b|\bm[uú]sica\b|\bdupla\b|\bdj\b|\bservi[cç]o[s]? art[ií]stico|\bapresenta[cç][aã]o musical\b|\batra[cç][aã]o musical\b') THEN 'Artistas, bandas e músicos' WHEN REGEXP_CONTAINS(texto,r'\bshow\b|\bshows\b|\bespet[aá]culo\b|\bfestival\b|\bprodu[cç][aã]o de evento\b|\borganiza[cç][aã]o de evento\b|\brealiza[cç][aã]o de evento\b|\bevento cultural\b|\bevento festivo\b') THEN 'Shows, festivais e produção de eventos' WHEN REGEXP_CONTAINS(texto,r'\bpalco\b|\bsonoriza[cç][aã]o\b|\bsom para (evento|festa|show)\b|\bilumina[cç][aã]o c[eé]nica\b|\btenda[s]?\b|\btoldos?\b|\btrio el[eé]trico\b|\bbanheiro[s]? qu[ií]mico[s]?\b|\bgerador para (evento|festa|show)\b|\bestrutura (para|de) (evento|festa|show)\b|\bloc[aç][aã]o de estrutura') AND REGEXP_CONTAINS(texto,r'evento|festa|show|festival|carnaval|s[aã]o jo[aã]o|festiv') THEN 'Estrutura e apoio para eventos' END categoria FROM b),f2 AS (SELECT * FROM f WHERE categoria IS NOT NULL),p AS (SELECT id_municipio,populacao FROM `basedosdados.br_ibge_populacao.municipio` WHERE ano=2025 AND sigla_uf='BA'),mt AS (SELECT f2.municipio, f2.id_municipio,ANY_VALUE(p.populacao) populacao_2025,COUNT(*) qtd,COUNTIF(f2.valor_total_homologado IS NOT NULL) qtd_h,SUM(f2.valor_total_homologado) val_h,SUM(f2.valor_total_estimado) val_e FROM f2 LEFT JOIN p USING(id_municipio) GROUP BY f2.municipio,f2.id_municipio),m25 AS (SELECT f2.municipio, f2.id_municipio,ANY_VALUE(p.populacao) populacao_2025,COUNT(*) qtd,COUNTIF(f2.valor_total_homologado IS NOT NULL) qtd_h,SUM(f2.valor_total_homologado) val_h,SUM(f2.valor_total_estimado) val_e,SAFE_DIVIDE(SUM(f2.valor_total_homologado),ANY_VALUE(p.populacao)) val_h_percapita FROM f2 LEFT JOIN p USING(id_municipio) WHERE f2.ano=2025 GROUP BY f2.municipio,f2.id_municipio)
SELECT 'total_2021_2026' tipo, * FROM (SELECT municipio,id_municipio,populacao_2025,qtd,qtd_h,val_h,val_e,CAST(NULL AS FLOAT64) val_h_percapita FROM mt QUALIFY ROW_NUMBER() OVER(ORDER BY val_h DESC NULLS LAST)<=20) UNION ALL SELECT 'ano_2025',* FROM (SELECT * FROM m25 QUALIFY ROW_NUMBER() OVER(ORDER BY val_h DESC NULLS LAST)<=20) UNION ALL SELECT 'per_capita_2025',* FROM (SELECT * FROM m25 WHERE val_h IS NOT NULL QUALIFY ROW_NUMBER() OVER(ORDER BY val_h_percapita DESC)<=20)